Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method ProcessHttpsRequest")

	Set ihcMrn=pRequest.ihcMrn
	Set jsonStreamObject = pRequest.jsonStreamObject
	Set msgType=pRequest.msgType

	Set tStream = ""
	Set tStream = ##class(%Stream.GlobalCharacter).%New()
	Do tStream.Write(jsonStreamObject.StringValue)		
	Set tStr = tStream.Read()
	$$$TRACE("JSON Request: ")
	if ($L(tStr)>1200){
		  $$$TRACE($E(tStr,1,1200))
		  $$$TRACE($E(tStr,1201,$L(tStr)))
	}else{
	      $$$TRACE(tStr)
	}
	Do tStream.Rewind()

	set URL = ..Adapter.URL
	$$$TRACE("Location: "_URL)

	Set httprequest=##class(%Net.HttpRequest).%New()
	Set httprequest.ContentType="application/json"
	Set credSettings = ..Adapter.Credentials
	Set cred=##class(Ens.Config.Credentials).%OpenId(credSettings)
    Set httprequest.Username= cred.Username
    Set httprequest.Password= cred.Password
	set httprequest.Timeout=..Adapter.ResponseTimeout
	$$$TRACE("Resp Timeout: "_httprequest.Timeout)	

	Do httprequest.EntityBody.Write() ;
	do httprequest.EntityBody.CopyFrom(tStream)
	try	{

		$$$TRACE("Calling Verato Post/merge identity Service.....")

		set postStatus = httprequest.Post(URL)		
		set postStatusTxt = $SYSTEM.Status.GetOneErrorText(postStatus)
		$$$TRACE("postStatusTxt-->  "_postStatusTxt)
		set response=httprequest.HttpResponse        
       	$$$TRACE("StatusLine: "_response.StatusLine) 
       	set statusLine = response.StatusLine 
       	set statusCode = ""
       	set statusDesc = ""
       	if (statusLine'=""){
			set statusCode=$piece(statusLine," ",2)
			set statusDesc=$piece(statusLine," ",3)			
      	}      
      	$$$TRACE("StatusCode: "_statusCode)  	     
      	$$$TRACE("StatusDesc: "_statusDesc)  
      	if (statusCode="401"){
	      	set tSC=##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Verato-Demogr-Json-Wsrc"," Could be an incorrect user authentication. Request :  "_tStr)
	    }
	    if ($LOCATE(statusCode,"5")= "1" ){
	      	set tSC=##class(IHC.ITF.ITFCOMMON.Utility).RetryCheckError("Out-Verato-Demogr-Json-Wsrc"," Unexpected Failure. Retrying.. Request :  "_tStr)
	    }	
		if (postStatus =1){
	    	$$$TRACE(" Demgr search service..Post status 1")   
	    	set len = httprequest.HttpResponse.ContentLength     
    		set respData = httprequest.HttpResponse.Data.Read()
    		$$$TRACE("RESP DATA ???? "_respData)   

    		set respJSONstring = respData
            set consumedJSONobj = ##class(%DynamicAbstractObject).%FromJSON(respJSONstring)
            set iter = consumedJSONobj.%GetIterator()
            set statusVal = consumedJSONobj.%Get("success")
            $$$TRACE(" Value of Success "_statusVal)             

          	if statusVal="1"{
	          $$$TRACE(" Search operation successful!!! ") 

	          set contentArr = (consumedJSONobj.%Get("content")) 
      		  Set arrObj = contentArr.%GetIterator()
      		  while arrObj.%GetNext(.key, .value){
	      		   //$$$TRACE("  key: "_key_" Value: "_value)
	      		  if (key = "searchResults"){
		      		  Set arrElem2Obj = value.%GetIterator()	
		      		  while arrElem2Obj.%GetNext(.key, .value) {
			      		  //$$$TRACE("  key2: "_key_" Value2: "_value)
			      		  If (key="0"){
	  			             Set arrElem3Obj = value.%GetIterator()
		  	                 while arrElem3Obj.%GetNext(.key, .value) {
			  	                 //$$$TRACE("  key3: "_key_" Value3: "_value)
			  	                 if (key="identity"){
				  	                 Set arrElem4Obj = value.%GetIterator()
				  	                  while arrElem4Obj.%GetNext(.key, .value) {
					  	                  //$$$TRACE("  key4: "_key_" Value4: "_value)
		  			       				  if ( (key ="sources")){
			  			       				  Set arrElem5Obj = value.%GetIterator()
			  			       				  while arrElem5Obj.%GetNext(.key, .value) {
				  			       				  Set arrElem6Obj = value.%GetIterator()
				  			       				  while arrElem6Obj.%GetNext(.key, .value) {
					  			       				  $$$TRACE("  key6: "_key_" Value6: "_value)
					  			       				  if (value="inmt.peaks"){
					  			       				  	set peaks = "1"
					  			       				  }					  			       				  
					  			       				  if ((key="id") && (peaks="1")){
						  			       				  set peaksMrn = value
						  			       				  $$$TRACE("Peaks mrn: "_peaksMrn)
						  			       				  set peaks="0"
						  			       			  }
				  			       				  }				  			       				  
			  			       				  }			  			       				  
		  			       				  }
				  	                  }		  			       			
			  	                 }
		  	                 }
			      		  }
		      		  }
	      		  }
      		  }
	      	}

	      	Set pResponse=##class(EnsLib.HTTP.GenericMessage).%New()
	      	do pResponse.StreamSet(httprequest.HttpResponse.Data)
		}
	}catch e{
		 $$$TRACE(" Unknown Exception: " _ e)
		 set errTxt = $System.Status.GetErrorText("Unknown Exception while calling Patient service POST operation to verato service "_e)		 
		 Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Verato-Demogr-Json-Wsrc",errTxt)	  		 		  		 		 
	}
	quit tSC
